/* A PC carries a segment (KUSEG 0x0..., KSEG0 0x8..., KSEG1 0xA...), and
 * code identity is the full PC: each body bakes the links, EPCs, fetch
 * tags and store PCs of the segment it was compiled for
 * (docs/SEGMENT_AWARE_CODE.md §5.5). Find the physical word's row, then
 * require the exact PC. A PC in another segment at the same word is a
 * segment miss: no row here, but still game text (physical), so dispatch
 * interprets it and records it, and never runs this body for it. */
static const PsxGameDispatchEntry* psx_game_find_entry(uint32_t addr) {
    const uint32_t want = addr & 0x1FFFFFFFu;
    const uint32_t offset = want - 0x00111288u;
    if ((want & 3u) || offset > 0x694u) return 0;
    const uint32_t index = k_psx_game_dispatch_index[offset >> 2];
    if (!index || k_psx_game_dispatch[index - 1u].addr != addr) return 0;
    return &k_psx_game_dispatch[index - 1u];
}

/* Exact static-code validity for this entry's emitted CFG ranges. */
int psx_game_text_native_ok(uint32_t addr) {
    const PsxGameDispatchEntry* entry = psx_game_find_entry(addr);
    if (!entry || entry->range_count == 0) return 0;
    return PSX_STATIC_CODE_VALID(&k_psx_game_validity[entry - k_psx_game_dispatch],
        &k_psx_game_code_ranges[entry->range_index].lo, entry->range_count, addr);
}

/* Full-range validity for straight-line interpreter-to-AOT handoff. */
int psx_game_text_native_ok_full(uint32_t addr) {
    const PsxGameDispatchEntry* entry = psx_game_find_entry(addr);
    if (!entry || entry->range_count == 0) return 0;
#if defined(PSX_NATIVE_STATIC_CALLS) && PSX_NATIVE_STATIC_CALLS
    return PSX_STATIC_CODE_VALID(&k_psx_game_validity[entry - k_psx_game_dispatch],
        &k_psx_game_code_ranges[entry->range_index].lo, entry->range_count, 0u);
#else
    return dirty_ram_text_native_ok_ranges(
        &k_psx_game_code_ranges[entry->range_index].lo, entry->range_count);
#endif
}

/* Maps PS1 address to compiled game code. Returns 1 if dispatched, 0 if unknown. */
int psx_dispatch_game_compiled(CPUState* cpu, uint32_t addr) {
    const PsxGameDispatchEntry* entry = psx_game_find_entry(addr);
    if (!entry) return 0;
    if (entry->range_count == 0 || !PSX_STATIC_CODE_VALID(
            &k_psx_game_validity[entry - k_psx_game_dispatch],
            &k_psx_game_code_ranges[entry->range_index].lo, entry->range_count, addr)) return 0;
    psx_check_interrupts_dispatch_entry(cpu, addr);
    cpu->pc = entry->resume_pc;
    /* load_accel: cycle-faithful VSync(-1) query (config-gated). */
    {
        extern int psx_vsync_query_hle_try(CPUState* cpu, uint32_t addr);
        if (psx_vsync_query_hle_try(cpu, addr)) return 1;
    }
#if defined(PSX_NATIVE_TAIL_CHAINS) && PSX_NATIVE_TAIL_CHAINS
    psx_native_tail_note_body(cpu, entry->fn);
#endif
    entry->fn(cpu);
    return 1;
}

/* PSX_NATIVE_TAIL_GAME_V1: same entry policy as the portable dispatcher. */
#if defined(PSX_NATIVE_TAIL_CHAINS) && PSX_NATIVE_TAIL_CHAINS
int psx_game_native_tail_enter(CPUState* cpu, uint32_t addr, PsxNativeTailBody body) {
    const PsxGameDispatchEntry* entry = psx_game_find_entry(addr);
    if (!entry || entry->fn != body) return 0;
    if (entry->range_count == 0 || !PSX_STATIC_CODE_VALID(
            &k_psx_game_validity[entry - k_psx_game_dispatch],
            &k_psx_game_code_ranges[entry->range_index].lo, entry->range_count, addr)) return 0;
    psx_check_interrupts_dispatch_entry(cpu, addr);
    cpu->pc = entry->resume_pc;
    /* load_accel: cycle-faithful VSync(-1) query (config-gated). */
    {
        extern int psx_vsync_query_hle_try(CPUState* cpu, uint32_t addr);
        if (psx_vsync_query_hle_try(cpu, addr)) return 2;
    }
    return 1;
}
#endif

/* 1 iff addr is a re-enterable compiled entry/continuation (no exec). */
int psx_game_is_function_entry(uint32_t addr) {
    return psx_game_find_entry(addr) != 0;
}

